def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    # Validate input
    if nanoseconds is None:
        return None
    if not isinstance(nanoseconds, int):
        raise TypeError(f"nanoseconds must be int, not {type(nanoseconds).__name__}")

    # Convert nanoseconds to hours, minutes, seconds, and microseconds
    sec, ns_remaining = divmod(nanoseconds, 1_000_000_000)
    hour, rem = divmod(sec, 3600)
    minute, second = divmod(rem, 60)
    microsecond = ns_remaining // 1000  # drop remaining nanoseconds

    # Construct a time object (assuming datetime is available in the surrounding scope)
    if tz is None:
        return datetime.time(hour, minute, second, microsecond)
    else:
        return datetime.time(hour, minute, second, microsecond, tzinfo=tz)

