def unit_of_work(metadata=None, timeout=None):
    """This function is a decorator for transaction functions that allows extra control over how the transaction is carried out."""
    def outer(inner):
        @functools.wraps(inner)
        def decorated(self, *args, **kwargs):
            # `self` is expected to be a session-like object that supports write_transaction
            def work(tx):
                return inner(tx, *args, **kwargs)
            return self.write_transaction(work, timeout=timeout, metadata=metadata)
        return decorated
    return outer

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Infer the driver from the first positional argument if it has a `.driver` attribute,
            # otherwise look for a `driver` keyword argument.
            driver = None
            if args and hasattr(args[0], "driver"):
                driver = args[0].driver
            if driver is None:
                driver = kwargs.pop("driver", None)

            if driver is None:
                raise ValueError(
                    "unit_of_work requires a `driver` instance either as a keyword argument "
                    "or via the first argument's `driver` attribute."
                )

            # Build transaction configuration
            tx_config = {}
            if timeout is not None:
                # Neo4j expects timeout in milliseconds
                tx_config["timeout"] = timeout * 1000
            if metadata is not None:
                tx_config["metadata"] = metadata

            # Begin a transaction, run the wrapped function, and close the transaction/driver
            with driver.session() as session:
                with session.begin_transaction(tx_config=tx_config) as tx:
                    return func(tx, *args, **kwargs)
        return wrapper
    return decorator

