    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # compute hash key, allowing key to accept either args/kwargs
            try:
                k = key(*args, **kwargs)
            except TypeError:
                k = key(args, kwargs)

            if k in cache:
                return cache[k]

            if lock is not None:
                lock.acquire()
                try:
                    if k in cache:
