def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if not isinstance(maxsize, int):
        raise TypeError('maxsize must be an integer')

    def decorating_function(user_function):
        from functools import wraps
        cache = {}
        # use an ordered dict to assist with MRU eviction (most recent at the end)
        from collections import OrderedDict
        hits = misses = 0

        @wraps(user_function)
        def wrapper(*args, **kwds):
            nonlocal hits, misses
            key = args
            if kwds:
                key += tuple(sorted(kwds.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwds:
                    key += tuple(type(v) for _, v in sorted(kwds.items()))
            if key in cache:
                hits += 1
                return cache[key]
            result = user_function(*args, **kwds)
            if maxsize != 0:
                cache[key] = result
                # Evict most recently used item if cache is full
                if len(cache) > maxsize:
                    # popitem(last=True) removes the last inserted item
                    cache.popitem(last=True)
            misses += 1
            return result

        wrapper.cache_info = lambda: (hits, misses, maxsize, len(cache))
        wrapper.cache_clear = lambda: (cache.clear(), setattr(wrapper, 'hits', 0), setattr(wrapper, 'misses', 0))
        return wrapper

    return decorating_function

