    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Build adjacency list and indegree count
    out_edges = {}
    indegree = {}
    appearance = {}
    next_index = 0

    for seq in orderings:
        for i, node in enumerate(seq):
            if node not in indegree:
                indegree[node] = 0
                out_edges[node] = set()
            if node not in appearance:
                appearance[node] = next_index
                next_index += 1
            if i > 0:
                prev = seq[i - 1]
                if node not in out_edges[prev]:
                    out_edges[prev].add(node)
                    indegree[node] += 1

    # Perform Kahn's algorithm with deterministic tie‑breaking
    zero_nodes = [node for node, deg in indegree.items() if deg == 0]
    # Sort by first appearance to preserve original relative order
    zero_nodes.sort(key=lambda n: appearance[n])
    result = []

    while zero_nodes:
        current = zero_nodes.pop(0)
        result.append(current)
        for succ in out_edges[current]:
            indegree[succ] -= 1
            if indegree[succ] == 0:
                # insert while maintaining appearance order
                inserted = False
                for idx, node in enumerate(zero_nodes):
                    if appearance[succ] < appearance[node]:
                        zero_nodes.insert(idx, succ)
                        inserted = True
                        break
                if not inserted:
                    zero_nodes.append(succ)

    if len(result) != len(appearance):
        raise ValueError("Cycle detected or missing nodes in ordering merge")

    return result

