        if isinstance(val, list):
            for v in val:
                v_str = _check_string(v, 'value')
                if v_str is not None:
                    if not value_re.match(v_str):
                        messages.append({v_str: f"Label value '{v_str}' does not match the regex [...]"})
        else:
            v_str = _check_string(val, 'value')
            if v_str is not None:
                if not value_re.match(v_str):
