def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        return

    for res in app.spec.manifest.values():
        # Skip if the resource already has an observer schema
        if getattr(res, "observer_schema", None) or res.get("observer_schema"):
            continue

        # Build a minimal default schema
        api_version = getattr(res, "apiVersion", None) or res.get("apiVersion", "v1")
        kind = getattr(res, "kind", None) or res.get("kind", "Resource")
        # Retrieve the name from metadata if possible
        if hasattr(res, "metadata") and isinstance(res.metadata, dict):
            name = res.metadata.get("name", None)
        else:
            name = res.get("metadata", {}).get("name", None)

        default_schema = {"apiVersion": api_version, "kind": kind}
        if name is not None:
            default_schema["metadata"] = {"name": name}

        # Attach the default schema back to the resource
        if isinstance(res, dict):
            res["observer_schema"] = default_schema
        else:
            setattr(res, "observer_schema", default_schema)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: Mapping from resource kind to its generated default observer schema.
    """
    # The result mapping from resource kind to the created default schema
    schemas = {}

    # Try to get the list of resources from the application's spec
    try:
        resources = getattr(app, "spec", None) and getattr(app.spec, "manifest", None)
    except AttributeError:
        resources = None

    # If no resources are available, just return an empty dict
    if not resources:
        return schemas

    # Helper to detect if a schema is already defined
    def has_custom_schema(resource):
        if isinstance(resource, dict):
            return "observer_schema" in resource or "custom_schema" in resource
        else:
            # object style
            return getattr(resource, "observer_schema", None) is not None or \
                   getattr(resource, "custom_schema", None) is not None

    # Helper to extract known information from a resource
    def get_resource_info(resource):
        if isinstance(resource, dict):
            kind = resource.get("kind") or resource.get("Kind")
            api_version = resource.get("apiVersion") or resource.get("API_VERSION")
            metadata = resource.get("metadata") or {}
            name = metadata.get("name")
        else:
            kind = getattr(resource, "kind", None) or getattr(resource, "Kind", None)
            api_version = getattr(resource, "api_version", None) or getattr(
                resource, "apiVersion", None) or getattr(resource, "API_VERSION", None)
            meta = getattr(resource, "metadata", None) or getattr(resource, "MetaData", None)
            name = getattr(meta, "name", None) if meta else None
        return kind, api_version, name

    for res in resources:
        # Skip resources that already declare a custom/observer schema
        if has_custom_schema(res):
            continue

        kind, api_version, name = get_resource_info(res)

        # Without a kind we cannot create a useful schema
        if not kind:
            continue

        # Build a minimal default observer schema
        default_schema = {
            "kind": kind,
            "apiVersion": api_version,
            "metadata": {}
        }
        if name:
            default_schema["metadata"]["name"] = name

        # Attach the default schema back to the resource
        if isinstance(res, dict):
            res["observer_schema"] = default_schema
        else:
            setattr(res, "observer_schema", default_schema)

        # Keep the schema in the result mapping; the last seen wins if duplicate kinds
        schemas[kind] = default_schema

    # Attach the mapping to the application if it accepts an `observer_schemas` attribute
    if hasattr(app, "observer_schemas"):
        app.observer_schemas.update(schemas)
    else:
        app.observer_schemas = schemas

    return schemas

