    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Verify that the application has the expected attributes
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        raise ValueError("The application object does not contain spec.manifest.")

    # Ensure an observer_schema dictionary exists
    observer_schema = getattr(app.spec, "observer_schema", None)
    if observer_schema is None:
        app.spec.observer_schema = {}
        observer_schema = app.spec.observer_schema

    # Iterate over all resources in the manifest
    for resource in app.spec.manifest:
        kind = resource.get("kind")
        if not kind:
            continue

        # Only create a default schema if one hasn't been supplied already
        if kind not in observer_schema:
            # Generate a minimal placeholder schema for the resource
            default_schema = {
                "type": kind,
                "metadata": {
                    "name": resource.get("metadata", {}).get("name", ""),
                },
            }
            observer_schema[kind] = default_schema

    return app

