def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if commands is None:
        raise ValueError("commands must not be None")

    # Build the command list
    if isinstance(commands, str):
        cmd = [commands]
    else:
        cmd = list(commands)

    # Append any additional args
    if args:
        cmd += list(args)

    if verbose:
        print(f"Running command: {' '.join(cmd)}")
        print(f"  cwd: {cwd}")
        print(f"  env: {env if env is not None else os.environ}")

    # Prepare the environment
    if env is not None:
        # Combine provided env with the current environment
        env_merged = os.environ.copy()
        env_merged.update(env)
    else:
        env_merged = None

    # Decide how to handle stderr
    if hide_stderr:
        stderr = subprocess.DEVNULL
    else:
        stderr = None

    # Execute the command
    try:
        completed = subprocess.run(
            cmd,
            cwd=cwd,
            env=env_merged,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=False
        )
    except FileNotFoundError as e:
        if verbose:
            print(f"Command not found: {cmd[0]}")
        raise e

    # Optionally print output if verbose
    if verbose and completed.stdout:
        print("Output:")
        print(completed.stdout)

    return completed

