        commands_to_run = [cmd]
    else:
        commands_to_run = []
        for cmd in commands:
            if isinstance(cmd, (list, tuple)):
                cmd_list = list(cmd)
            else:
                cmd_list = [cmd]
            cmd_list.extend(args if isinstance(args, list) else [args])
            commands_to_run.append(cmd_list)

    # Execute the command(s)
    last_output = None
    for cmd in commands_to_run:
        if verbose:
            print("Running:", " ".join(map(str, cmd)), file=sys.stderr)
        process = subprocess.Popen(
            cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
            env=env,
            text=True,
        )
        stdout, stderr = process.communicate()
        if process.returncode != 0:
            raise RuntimeError(
                f"Command '{' '.join(cmd)}' failed with return code {process.returncode}"
                f"{' and stderr: ' + stderr if not hide_stderr else ''}"
            )
        last_output = stdout

    return last_output

