def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import xml.etree.ElementTree as ET

    def _parse_inventory(path):
        """Return a dict mapping file paths to their digests."""
        tree = ET.parse(path)
        root = tree.getroot()
        digests = {}
        # Assume the XML structure has <file path="..." digest="..."/> elements
        for file_el in root.findall('.//file'):
            fp = file_el.get('path')
            val = file_el.get('digest')
            if fp and val:
                digests[fp] = val
        return digests

    root_digests = None
    for idx, ver_dir in enumerate(version_dirs):
        inv_path = os.path.join(ver_dir, 'inventory.xml')
        if not os.path.exists(inv_path):
            raise FileNotFoundError(f"Missing inventory in version directory '{ver_dir}'")
        cur_digests = _parse_inventory(inv_path)

        if idx == 0:
            root_digests = cur_digests
            continue

        # Check that current inventory contains all files present up to this point
        missing = set(root_digests.keys()) - set(cur_digests.keys())
        if missing:
            raise ValueError(f"Inventory in '{ver_dir}' is missing files: {', '.join(missing)}")

        # Record any digest differences from the root inventory
        diffs = {}
        for key, root_val in root_digests.items():
            cur_val = cur_digests.get(key)
            if cur_val is None:
                continue
            if cur_val != root_val:
                diffs[key] = (root_val, cur_val)
        if diffs:
            raise ValueError(f"Digest differences in '{ver_dir}': {diffs}")

        # Update root_digests to include any new files since latest inventory
        for k, v in cur_digests.items():
            root_digests.setdefault(k, v)

    return True

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import xml.etree.ElementTree as ET

    # Ensure containers for differences and inventories exist
    if not hasattr(self, "_inventory_diffs"):
        self._inventory_diffs = {}
    if not hasattr(self, "inventories"):
        self.inventories = {}

    # Load root inventory once if it hasn't been loaded already
    if not hasattr(self, "root_inventory_digest"):
        root_path = os.path.join(self.root_dir, "inventory.xml")
        if os.path.exists(root_path):
            try:
                root_tree = ET.parse(root_path)
                self.root_inventory_digest = {
                    elem.get("type"): elem.get("value")
                    for elem in root_tree.iter("digest")
                }
            except ET.ParseError as exc:
                raise ValueError(f"Failed to parse root inventory '{root_path}': {exc}")
        else:
            self.root_inventory_digest = {}

    # Iterate over each version directory
    for vdir in version_dirs:
        inv_path = os.path.join(vdir, "inventory.xml")
        if not os.path.exists(inv_path):
            raise ValueError(f"Missing inventory for version directory '{vdir}'.")
        try:
            tree = ET.parse(inv_path)
        except ET.ParseError as exc:
            raise ValueError(f"Failed to parse inventory '{inv_path}': {exc}")

        # Extract digests from this inventory
        digests = {
            elem.get("type"): elem.get("value")
            for elem in tree.iter("digest")
        }

        # Check for differences with the root inventory
        diff = {
            t: v
            for t, v in digests.items()
            if t in self.root_inventory_digest and v != self.root_inventory_digest[t]
        }
        if diff:
            self._inventory_diffs[vdir] = diff

        # Store the inventory for possible future checks
        self.inventories[vdir] = digests

