def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import re

    if not os.path.exists(path):
        return f"path '{path}' does not exist"

    if os.path.isfile(path):
        return "file"

    if os.path.isdir(path):
        # Check for Namaste files that start with "0=".
        for dirpath, dirnames, filenames in os.walk(path):
            for fn in filenames:
                # Common Namaste filename patterns can be ".namestafile"
                if fn.startswith('.namestafile') or fn.endswith('.namestafile'):
                    file_path = os.path.join(dirpath, fn)
                    try:
                        with open(file_path, 'r', encoding='utf-8') as f:
                            first_line = f.readline().strip()
                        match = re.match(r'^0=(\S+)', first_line)
                        if match:
                            tag = match.group(1).lower()
                            if tag == 'repo-root' or tag == 'root':
                                return 'root'
                            elif tag == 'object':
                                return 'object'
                    except Exception:
                        # ignore unreadable files
                        pass

        # If no explicit Namaste file found, use directory structure heuristics.
        # OCFL root usually contains an 'objects' directory.
        if os.path.isdir(os.path.join(path, 'objects')):
            return 'root'
        # An OCFL object may contain a 'v1' or 'inventory' file.
        for sub in ('v1', 'inventory'):
            if os.path.exists(os.path.join(path, sub)):
                return 'object'

    return f"unable to determine type for path '{path}'"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os, re

    # Verify path exists
    if not os.path.exists(path):
        return f"error: path does not exist: {path}"

    # Handle files
    if os.path.isfile(path):
        return "file"

    # Handle directories
    if os.path.isdir(path):
        namaste_pattern = re.compile(r"^0=")  # matches files starting with '0='
        try:
            entries = os.listdir(path)
        except OSError as exc:
            return f"error: {exc}"

        # Check for a direct Namaste file (root indicator)
        for entry in entries:
            if namaste_pattern.match(entry):
                return "root"

        # Check subdirectories for Namaste files (object indicator)
        for entry in entries:
            subpath = os.path.join(path, entry)
            if os.path.isdir(subpath):
                try:
                    subentries = os.listdir(subpath)
                except OSError:
                    continue
                if any(namaste_pattern.match(e) for e in subentries):
                    return "object"

        # If none matched, return unknown
        return "unknown"

    # If it's neither file nor directory
    return "unknown"

