def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    if not bug_ids:
        return
    if isinstance(bug_ids, (list, tuple, set)):
        ids = ','.join(str(b) for b in bug_ids)
    else:
        ids = str(bug_ids)
    existing = params.get('ids')
    if existing:
        if isinstance(existing, str):
            params['ids'] = f"{existing},{ids}"
        else:
            params['ids'] = ids
    else:
        params['ids'] = ids

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    # Bugzilla expects a comma separated list of IDs in the 'ids' parameter
    if isinstance(bug_ids, (list, tuple)):
        params['ids'] = ','.join(str(bid) for bid in bug_ids)
    else:
        params['ids'] = str(bug_ids)
    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    assert isinstance(params, dict), "params must be a dictionary"
    if not isinstance(bug_ids, (list, tuple)):
        bug_ids = [bug_ids]
    # Convert existing IDs to a set of strings
    if "ids" in params:
        existing = params["ids"]
        if isinstance(existing, str):
            existing_set = set(existing.split(","))
        else:
            existing_set = set(str(b) for b in existing)
    else:
        existing_set = set()
    # Merge with new bug IDs
    bug_id_set = set(str(b) for b in bug_ids)
    merged = existing_set | bug_id_set
    params["ids"] = ",".join(sorted(merged, key=lambda x: int(x)))
    return params

