def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    from collections import OrderedDict

    def merge_mapping_nodes(a, b):
        """
        Merge two MappingNodes a and b, where b is merged into a. Keys in b override or
        extend those in a. If a value for a key is itself a MappingNode in both a and b,
        merge them recursively.
        """
        a_list = a.value
        b_list = b.value

        # Prepare a dict of b items for quick lookup by key string
        b_dict = OrderedDict()
        for b_key_node, b_val_node in b_list:
            b_dict[b_key_node.value] = (b_key_node, b_val_node)

        result_list = []
        used_b_keys = set()

        # Iterate over a's items to preserve order
        for a_key_node, a_val_node in a_list:
            key = a_key_node.value
            if key in b_dict:
                b_key_node, b_val_node = b_dict[key]
                # Prefer key node from a (original)
                if isinstance(a_val_node, MappingNode) and isinstance(b_val_node, MappingNode):
                    merged_val = merge_mapping_nodes(a_val_node, b_val_node)
                else:
                    merged_val = b_val_node
                result_list.append((a_key_node, merged_val))
                used_b_keys.add(key)
            else:
                result_list.append((a_key_node, a_val_node))

        # Add remaining items from b that were not in a
        for key, (b_key_node, b_val_node) in b_dict.items():
            if key not in used_b_keys:
                result_list.append((b_key_node, b_val_node))

        # Preserve the tag from the original mapping node a
        return type(a)(tag=a.tag, value=result_list)

    merged_map = OrderedDict()

    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_map:
            existing_key_node, existing_value_node = merged_map[key]
            if isinstance(existing_value_node, type(value_node)):
                # If both values are MappingNode, deep merge them
                if isinstance(existing_value_node, ruamel.yaml.nodes.MappingNode):
                    merged_value = merge_mapping_nodes(existing_value_node, value_node)
                else:
                    # Non-mapping values: last value wins
                    merged_value = value_node
            else:
                merged_value = value_node
            merged_map[key] = (existing_key_node, merged_value)
        else:
            merged_map[key] = (key_node, value_node)

    return list(merged_map.values())

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def merge_mappings(old, new):
        old_list = old.value
        new_list = new.value
        old_index_map = {k.value: i for i, (k, _) in enumerate(old_list)}
        for new_key, new_val in new_list:
            key = new_key.value
            if key in old_index_map:
                idx = old_index_map[key]
                old_key, old_val = old_list[idx]
                if type(old_val).__name__ == 'MappingNode' and type(new_val).__name__ == 'MappingNode':
                    merge_mappings(old_val, new_val)
                else:
                    old_list[idx] = (new_key, new_val)
            else:
                old_list.append((new_key, new_val))

    merged = {}
    order = []

    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged:
            merged[key] = (key_node, value_node)
            order.append(key)
        else:
            old_key_node, old_value_node = merged[key]
            if type(old_value_node).__name__ == 'MappingNode' and type(value_node).__name__ == 'MappingNode':
                merge_mappings(old_value_node, value_node)
            else:
                merged[key] = (key_node, value_node)

    return [(merged[k][0], merged[k][1]) for k in order]

