def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url

    import re

    def _repl(match):
        key = match.group(1)
        if key in url_args:
            return str(url_args[key])
        return match.group(0)

    # Replace {key} placeholders
    url = re.sub(r'\{([^{}]+)\}', _repl, url)
    # Replace %(key)s placeholders
    url = re.sub(r'%\(([^)]+)\)s', _repl, url)

    return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url
    import re
    pattern = re.compile(r'\{([^}]+)\}|\%\(([^)]+)\)s')
    def _replace(match):
        key = match.group(1) or match.group(2)
