def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None:
        return None

    fv = frequency.strip().lower()
    if fv == "always":
        return None

    parts = fv.split()
    if not parts or len(parts) < 2:
        raise ValueError(f"Invalid frequency format: '{frequency}'")

    # Try to parse the first part as a number
    try:
        # Allow integer or float
        if '.' in parts[0]:
            amount = float(parts[0])
        else:
            amount = int(parts[0])
    except ValueError:
        raise ValueError(f"Invalid number in frequency: '{parts[0]}'")

    # Combine remaining parts to form the unit string
    unit = ' '.join(parts[1:])

    # Map unit strings to timedelta keyword arguments
    unit_map = {
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
        'hour': 'hours',
        'hours': 'hours',
        'minute': 'minutes',
        'minutes': 'minutes',
        'second': 'seconds',
        'seconds': 'seconds',
    }

    # Strip potential plural 's' if not directly in map
    keyword = unit_map.get(unit, None)
    if keyword is None:
        # Try singular by removing trailing 's' if present
        if unit.endswith('s'):
            keyword = unit_map.get(unit[:-1], None)
        if keyword is None:
            raise ValueError(f"Unrecognized time unit in frequency: '{unit}'")

    # Build the keyword argument dictionary
    kwargs = {keyword: amount}
    return datetime.timedelta(**kwargs)

