    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Attempt to extract the variable name from the matcher.
    name = None
    default = None

    # If matcher behaves like a regex Match object, use group(1) for the variable name.
    if hasattr(matcher, 'group'):
        try:
            name = matcher.group(1)
        except Exception:
            raise ValueError("Unable to extract variable name from matcher.")
        # Group 2 often contains a default value if present.
        try:
            default = matcher.group(2)
        except Exception:
            pass
    # Fallback: if matcher is a tuple/list-like, assume first element is name, second is default.
    elif isinstance(matcher, (list, tuple)):
        if len(matcher) >= 1:
            name = matcher[0]
        if len(matcher) >= 2:
            default = matcher[1]
    else:
        raise ValueError("Matcher must provide variable name via group() or index.")

    if name is None:
        raise ValueError("Variable name could not be determined from matcher.")

    # Resolve environment variable
    if name in os.environ:
        return os.environ[name]
    if default is not None:
        return default
    raise KeyError(f"Environment variable '{name}' not found and no default value provided.")

