def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    parsed = urllib.parse.urlparse(image_href)
    # If we have a scheme and netloc, treat as URL
    if parsed.scheme and parsed.netloc:
        if parsed.scheme not in ('http', 'https'):
            raise ValueError(f"Unsupported scheme '{parsed.scheme}' in image href '{image_href}'")
        use_ssl = parsed.scheme == 'https'
        netloc = parsed.netloc
        path = parsed.path
        if path.endswith('/'):
            raise ValueError(f"Image href '{image_href}' does not point to a specific image")
        image_id = path.split('/')[-1]
        if not image_id:
            raise ValueError(f"Could not determine image id from href '{image_href}'")
        return (image_id, netloc, use_ssl)
    # No scheme/netloc: maybe a local or relative path
    if not parsed.scheme and not parsed.netloc:
        image_id = image_href.split('/')[-1]
        if not image_id:
            raise ValueError(f"Invalid image href '{image_href}' - cannot extract image id")
        return (image_id, '', False)
    raise ValueError(f"Image href '{image_href}' is malformed")

